const KEY='heart-notes-v1';
const defaults=()=>({categories:structuredClone(SEED_CATEGORIES),questions:structuredClone(SEED_QUESTIONS),favorites:[],players:[],seen:[],round:0,preview:true,unique:true,selected:'random',randomCats:SEED_CATEGORIES.map(c=>c.id),type:'mix',playerMode:'manual',currentPlayer:'',partner:'',current:null});
let db;let storageOK=true;try{db=JSON.parse(localStorage.getItem(KEY))||defaults()}catch{db=defaults();storageOK=false}let page='game',filterCat='all',query='',filterType='all',revealed=!db.preview;
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const uid=()=>crypto.randomUUID();
const icons={game:'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="m4 7 8 6 8-6M9 3h6"/>',library:'<path d="M4 4h6v16H4zM10 4h6v16h-6zM17 5l3-1 3 15-3 1z"/>',heart:'<path d="M20 5c-3-3-7-1-8 1-1-2-5-4-8-1-4 4 0 9 8 15 8-6 12-11 8-15z"/>',players:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3c0-5 12-5 12 0v3M16 5a3 3 0 0 1 0 6M18 14c3 0 4 2 4 5"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="8" cy="18" r="2" fill="currentColor"/>',shuffle:'<path d="M3 6h3c5 0 7 12 12 12h3M3 18h3c5 0 7-12 12-12h3M18 3l3 3-3 3M18 15l3 3-3 3"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.heart}</svg>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch{storageOK=false;toast('设备存储不可用，请在设置中导出备份')}}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
const cat=id=>db.categories.find(c=>c.id===id);const player=id=>db.players.find(p=>p.id===id);const typeName=t=>t==='truth'?'真心话':'大冒险';
const flower=`<svg class="flower" viewBox="0 0 120 120" fill="none" aria-hidden="true"><path d="M60 102V52M60 84C42 85 34 73 33 67c16-2 24 6 27 17M61 72c18 0 24-12 26-19-16-1-24 8-26 19" stroke="#b4bba4" stroke-width="1.5"/><g fill="#e9cad8" stroke="#cf9cb5" stroke-width="1"><ellipse cx="60" cy="34" rx="12" ry="21"/><ellipse cx="60" cy="34" rx="12" ry="21" transform="rotate(72 60 46)"/><ellipse cx="60" cy="34" rx="12" ry="21" transform="rotate(144 60 46)"/><ellipse cx="60" cy="34" rx="12" ry="21" transform="rotate(216 60 46)"/><ellipse cx="60" cy="34" rx="12" ry="21" transform="rotate(288 60 46)"/></g><circle cx="60" cy="46" r="7" fill="#f8edd5"/><path d="m96 26 2 4 4 1-4 1-2 4-1-4-4-1 4-1zM20 45l2 3 3 1-3 1-2 3-1-3-3-1 3-1z" fill="#c6b2cb"/></svg>`;
function render(){const nav=[['game','今晚开局'],['library','我的题库'],['favorites','心动收藏'],['players','在场玩家'],['settings','偏好设置']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand serif"><img src="icon.svg" alt="">心动纸条</div><div class="brand-sub">HEART NOTES</div><nav class="nav" aria-label="主导航">${nav.map(([id,label])=>`<button data-action="nav" data-id="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id==='favorites'?'heart':id)}<span>${label}</span></button>`).join('')}</nav><div class="side-foot">把话留在今晚，<br>把温柔带给彼此。<br><span style="font-size:17px;color:#c79cb3">♡</span></div></aside><main class="main"><div class="topbar"><span class="desktop-label">A LITTLE CLOSER, TONIGHT</span><div class="mobile-brand brand serif"><img src="icon.svg" alt="">心动纸条</div><span class="pill">✧ ${db.players.length?db.players.length+' 位玩家，已就位':'为她们的相聚'}</span></div>${page==='game'?gameView():page==='library'||page==='favorites'?libraryView():page==='players'?playersView():settingsView()}<div class="footer">♡ 自在表达，温柔靠近 ♡</div></main></div>`;}
function gameView(){let q=db.current,c=q&&cat(q.category),p=player(db.currentPlayer),partner=player(db.partner);return `<header class="intro"><div><span class="eyebrow">TONIGHT IS OURS</span><h1>今晚，靠近一点。</h1><p>从一张小纸条开始，认识更真实的彼此。</p></div>${flower}</header><div class="game-layout"><section class="panel game-main"><div class="panel-head"><span class="section-label">选择今晚的氛围</span><button class="text-btn" data-action="random-config">混合设置 ⚙</button></div><div class="categories">${[...db.categories,{id:'random',name:'随机',symbol:'✧'},...(db.selected==='favorites'?[{id:'favorites',name:'收藏',symbol:'♥'}]:[])].map(c=>`<button class="cat ${db.selected===c.id?'selected':''}" data-action="category" data-id="${esc(c.id)}" aria-pressed="${db.selected===c.id}"><span class="symbol">${esc(c.symbol)}</span>${esc(c.name)}</button>`).join('')}</div><div class="segmented" aria-label="题型">${[['mix','随心混合'],['truth','真心话'],['dare','大冒险']].map(([id,n])=>`<button data-action="type" data-id="${id}" class="${db.type===id?'active':''}" aria-pressed="${db.type===id}">${n}</button>`).join('')}</div><div class="paper-wrap"><article class="paper" id="paper"><div class="paper-meta">${q?esc(c?.name||'专属纸条')+' · '+typeName(q.type):'一张纸条，一次靠近'}</div><p class="question">${q?(revealed?esc(q.text):'这张纸条，<br>先让主持人看一眼。'):'有些话，<br>想慢慢说给你听。'}</p>${q&&!revealed?'<button class="secondary reveal" data-action="preview">主持人查看</button>':`<div class="hint">${q?esc(q.level)+' · '+(q.people===2?'双人互动':'自在分享'):'选好氛围，抽取属于今晚的第一张纸条'}</div>`}<div class="paper-bottom"><span>${q?(p?esc(p.name):'由主持人邀请')+(partner?' × '+esc(partner.name):''):'HEART NOTES · ONLY FOR US'}</span>${q?`<button class="icon-btn" data-action="favorite" data-id="${esc(q.id)}" aria-label="${db.favorites.includes(q.id)?'取消收藏':'收藏题目'}" aria-pressed="${db.favorites.includes(q.id)}">${db.favorites.includes(q.id)?'♥':icon('heart')}</button>`:'<span>♡</span>'}</div></article></div><button class="primary draw" data-action="draw">${icon('shuffle')} ${q?'抽取下一张纸条':'抽一张心动纸条'}</button><div class="actions"><button class="text-btn" data-action="skip" ${q?'':'disabled'}>跳过这张</button><span class="muted">·</span><button class="text-btn" data-action="reset-round">重新开局</button></div><div class="round-info"><span>今晚已抽 ${db.round} 张</span><span>${db.unique?'本场不重复':'允许重复'} · 当前可抽 ${pool().length} 张</span></div></section><aside class="game-aside"><section class="panel side-panel"><div class="panel-head"><h3>这一轮，谁来？</h3><button data-action="nav" data-id="players" class="text-btn">管理</button></div><div class="player-current"><span class="avatar">${p?esc(p.name.slice(0,1)):'♡'}</span><div><strong>${p?esc(p.name):'自由邀请'}</strong><small>${db.playerMode==='random'?'抽题时随机选人':'由主持人选择玩家'}</small></div></div><div class="player-select"><button data-action="player-mode" data-id="manual" class="${db.playerMode==='manual'?'chosen':''}">指定玩家</button><button data-action="player-mode" data-id="random" class="${db.playerMode==='random'?'chosen':''}">随机选人</button></div>${db.players.length?`<label class="fine" for="current-player">当前玩家</label><select id="current-player"><option value="">自由邀请</option>${db.players.map(p=>`<option value="${p.id}" ${db.currentPlayer===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label class="fine" for="partner">互动搭档（可选）</label><select id="partner"><option value="">现场邀请</option>${db.players.filter(p=>p.id!==db.currentPlayer).map(p=>`<option value="${p.id}" ${db.partner===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:'<button class="text-btn" data-action="add-player">＋ 添加今晚的玩家</button>'}</section><section class="panel side-panel"><h3>主持人的小开关</h3><label class="switch-row">抽题后先由主持人预览<input type="checkbox" data-setting="preview" ${db.preview?'checked':''}></label><label class="switch-row">本场题目不重复<input type="checkbox" data-setting="unique" ${db.unique?'checked':''}></label></section><div class="note"><span class="serif" style="font-size:16px">给今晚的一点温柔 ♡</span><p>可以真诚，也可以害羞。<br>任何题目都可以跳过；双人互动，先问一句「你愿意吗？」</p></div></aside></div>`;}
function pool(){return db.questions.filter(q=>(db.selected==='favorites'?db.favorites.includes(q.id):db.selected==='random'?db.randomCats.includes(q.category):q.category===db.selected)&&(db.type==='mix'||q.type===db.type)&&(!db.unique||!db.seen.includes(q.id)))}
function libraryView(){let fav=page==='favorites';let list=db.questions.filter(q=>(!fav||db.favorites.includes(q.id))&&(filterCat==='all'||q.category===filterCat)&&(filterType==='all'||q.type===filterType)&&q.text.toLowerCase().includes(query.toLowerCase()));return `<header class="page-heading"><div><h1>${fav?'把心动，留下来。':'属于你们的题库'}</h1><p>${fav?'收藏那些想再聊一次的话题。':db.questions.length+' 张纸条，等一个打开话题的时刻。'}</p></div><button class="primary" data-action="add-question">＋ 新增题目</button></header>${fav?'<button class="secondary" data-action="draw-favorites" style="margin-bottom:18px">♡ 从收藏中抽一张</button>':''}<div class="toolbar"><input id="search" placeholder="搜索纸条里的关键词…" aria-label="搜索题目" value="${esc(query)}"><select id="filter-type" aria-label="筛选题型"><option value="all">全部题型</option><option value="truth" ${filterType==='truth'?'selected':''}>真心话</option><option value="dare" ${filterType==='dare'?'selected':''}>大冒险</option></select><button class="secondary" data-action="add-category">＋ 新建题库</button></div><div class="chips"><button class="chip ${filterCat==='all'?'active':''}" data-action="filter" data-id="all">全部</button>${db.categories.map(c=>`<button class="chip ${filterCat===c.id?'active':''}" data-action="filter" data-id="${c.id}">${esc(c.symbol)} ${esc(c.name)}</button>`).join('')}</div><div class="panel-head"><small>共 ${list.length} 张纸条</small>${!fav&&filterCat!=='all'?`<button class="text-btn" data-action="manage-category" data-id="${esc(filterCat)}">管理此题库</button>`:''}</div><div class="question-list">${list.length?list.map(q=>`<article class="question-row"><div><div class="tags"><span>${esc(cat(q.category)?.name)}</span><span>${typeName(q.type)}</span><span>${esc(q.level)}${q.people===2?' · 双人':''}</span></div><p>${esc(q.text)}</p></div><div class="row-actions"><button class="icon-btn" data-action="favorite" data-id="${q.id}" aria-label="${db.favorites.includes(q.id)?'取消收藏':'收藏'}" aria-pressed="${db.favorites.includes(q.id)}">${db.favorites.includes(q.id)?'♥':'♡'}</button><button data-action="edit-question" data-id="${q.id}">编辑</button></div></article>`).join(''):`<div class="empty">${fav?'还没有收藏的纸条。<br>遇到喜欢的话题，点一下 ♡。':'这里还没有合适的纸条。<br>换个关键词，或新增第一张。'}</div>`}</div>`;}
function playersView(){return `<header class="page-heading"><div><h1>今晚，有你们。</h1><p>昵称就好，让每个人都自在加入。</p></div><button class="primary" data-action="add-player">＋ 添加玩家</button></header><div class="grid2">${db.players.map(p=>`<div class="player-card"><div><span class="avatar">${esc(p.name.slice(0,1))}</span><strong>${esc(p.name)}</strong></div><div><button class="text-btn" data-action="edit-player" data-id="${p.id}">编辑</button><button class="text-btn" data-action="remove-player" data-id="${p.id}">移除</button></div></div>`).join('')}</div>${!db.players.length?'<div class="empty">还没有玩家加入。<br>添加昵称，就可以指定或随机选择玩家。</div>':''}<div class="note" style="margin-top:25px"><h3>让每个人都有自己的节奏</h3><p>随机选人会在每次抽题时重新选择；你也可以在开局页面指定玩家和互动搭档。没有名单时，仍可自由抽题。</p></div>`;}
function settingsView(){return `<header class="page-heading"><div><h1>把今晚，安排好。</h1><p>一些小设置，让相聚更顺手。</p></div></header><div class="settings-stack"><section class="panel"><h2>抽题偏好</h2><label class="switch-row">主持人先预览，再展示给大家<input type="checkbox" data-setting="preview" ${db.preview?'checked':''}></label><label class="switch-row">本场题目不重复<input type="checkbox" data-setting="unique" ${db.unique?'checked':''}></label><p>当前已抽 ${db.round} 张。重新开局会清空抽题记录，保留题库、玩家和收藏。</p><button class="secondary" data-action="reset-round">重新开局</button></section><section class="panel"><h2>题库与数据备份</h2><p>题库、玩家和收藏保存在当前浏览器中，${storageOK?'不会自动同步到其他设备':'当前设备存储不可用，请及时备份'}。清理浏览器数据前，记得导出备份。</p><div class="stack-actions"><button class="primary" data-action="export">导出完整备份</button><button class="secondary" data-action="import">导入备份</button></div><input type="file" id="import-file" accept=".json,application/json" hidden><p style="margin:14px 0 0">导入时可选择合并题库或恢复完整备份。</p></section><section class="panel"><h2>放到手机桌面</h2><p>iPhone：用 Safari 打开网址，点击分享，选择「添加到主屏幕」。<br>安卓：在浏览器菜单中选择「添加到主屏幕」或「安装应用」（以浏览器支持为准）。</p><span class="fine">心动纸条 · 为她们的相聚而做 ♡</span></section></div>`;}
function modal(html){$('#dialog').innerHTML=html;$('#dialog').showModal()}
function confirmBox(title,body,action,label='确认'){modal(`<h2>${title}</h2><p class="fine">${body}</p><div class="dialog-actions"><button class="secondary" data-action="close">取消</button><button class="primary" id="confirm-do">${label}</button></div>`);$('#confirm-do').onclick=()=>{$('#dialog').close();action()};}
function questionForm(id){let q=db.questions.find(q=>q.id===id);modal(`<form id="question-form"><h2>${q?'编辑这张纸条':'写一张新纸条'}</h2><label for="q-text">题目内容</label><textarea id="q-text" name="text" required maxlength="1000" placeholder="你想问她们什么？">${esc(q?.text||'')}</textarea><div class="form-row"><div><label for="q-cat">所属题库</label><select id="q-cat" name="category">${db.categories.map(c=>`<option value="${c.id}" ${(q?.category||filterCat)===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div><label for="q-type">题型</label><select id="q-type" name="type"><option value="truth">真心话</option><option value="dare" ${q?.type==='dare'?'selected':''}>大冒险</option></select></div><div><label for="q-level">氛围强度</label><select id="q-level" name="level">${['轻松','微甜','走心','刺激'].map(v=>`<option ${q?.level===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="q-people">参与方式</label><select id="q-people" name="people"><option value="1">单人 / 自由邀请</option><option value="2" ${q?.people===2?'selected':''}>双人互动</option></select></div></div><div class="dialog-actions">${q?`<button type="button" class="text-btn" data-action="delete-question" data-id="${q.id}">删除</button>`:''}<button type="button" class="secondary" data-action="close">取消</button><button class="primary">保存纸条</button></div></form>`);$('#question-form').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.text=data.text.trim();if(!data.text)return toast('请写下题目内容');data.people=Number(data.people);if(q){Object.assign(q,data);if(db.current?.id===id)db.current={...q}}else db.questions.push({id:uid(),...data});save();$('#dialog').close();render();toast('纸条已保存')};}
function playerForm(id){let p=player(id);modal(`<form id="player-form"><h2>${p?'编辑昵称':'欢迎加入今晚'}</h2><label for="p-name">玩家昵称（最多12字）</label><input id="p-name" name="name" maxlength="12" required value="${esc(p?.name||'')}" placeholder="大家怎么称呼你？"><div class="dialog-actions"><button type="button" class="secondary" data-action="close">取消</button><button class="primary">保存玩家</button></div></form>`);$('#player-form').onsubmit=e=>{e.preventDefault();let name=new FormData(e.target).get('name').trim();if(!name)return toast('请填写昵称');if(db.players.some(x=>x.id!==id&&x.name===name))return toast('这个昵称已经在场啦，换一个吧');p?p.name=name:db.players.push({id:uid(),name});save();$('#dialog').close();render();toast('玩家已保存')};}
function categoryForm(id){let c=cat(id);modal(`<form id="category-form"><h2>${c?'管理题库':'新建专属题库'}</h2><label for="c-name">题库名称</label><input id="c-name" name="name" required maxlength="12" value="${esc(c?.name||'')}" placeholder="例如：生日心愿库"><div class="dialog-actions">${c?'<button type="button" class="text-btn" id="delete-cat">删除题库</button>':''}<button type="button" class="secondary" data-action="close">取消</button><button class="primary">保存题库</button></div></form>`);$('#category-form').onsubmit=e=>{e.preventDefault();let name=new FormData(e.target).get('name').trim();if(!name)return toast('请填写题库名称');if(db.categories.some(x=>x.id!==id&&x.name===name))return toast('已有同名题库');if(c)c.name=name;else{let id=uid();db.categories.push({id,name,symbol:'✿'});db.randomCats.push(id);filterCat=id}save();$('#dialog').close();render()};if(c)$('#delete-cat').onclick=()=>{if(db.categories.length===1)return toast('至少保留一个题库');confirmBox('删除这个题库？','其中的题目和对应收藏也会删除。建议先导出备份。',()=>{const ids=db.questions.filter(q=>q.category===id).map(q=>q.id);db.categories=db.categories.filter(x=>x.id!==id);db.questions=db.questions.filter(q=>q.category!==id);db.favorites=db.favorites.filter(x=>!ids.includes(x));db.randomCats=db.randomCats.filter(x=>x!==id);if(db.selected===id)db.selected='random';if(db.current?.category===id)db.current=null;filterCat='all';save();render()},'删除题库')};}
function pick(items){const a=new Uint32Array(1);crypto.getRandomValues(a);return items[Math.floor(a[0]/4294967296*items.length)]}
function draw(){let items=pool();if(!items.length){toast('当前没有可抽题目，请切换分类或重新开局');return}let q=pick(items);db.current={...q};db.seen=[...new Set([...db.seen,q.id])];db.round++;revealed=!db.preview;if(db.playerMode==='random'&&db.players.length){const p=pick(db.players);db.currentPlayer=p.id;db.partner='';if(q.people===2&&db.players.length>1)db.partner=pick(db.players.filter(x=>x.id!==p.id)).id}save();render();$('#paper').classList.add('flip');}
const actions={'draw-favorites':()=>{db.selected='favorites';page='game';save();draw();window.scrollTo(0,0)},nav:id=>{page=id;query='';filterCat='all';filterType='all';render();window.scrollTo(0,0)},category:id=>{db.selected=id;save();render()},type:id=>{db.type=id;save();render()},draw,skip:()=>{toast('已跳过，换一张纸条');draw()},'reset-round':()=>confirmBox('开始新的一局？','清空本场抽题记录，所有题目都可以重新抽取。',()=>{db.seen=[];db.round=0;db.current=null;save();render();toast('新的一局，温柔开始')}),'player-mode':id=>{db.playerMode=id;save();render();if(id==='random'&&!db.players.length)toast('先添加玩家，就可以随机选人啦')},favorite:id=>{db.favorites=db.favorites.includes(id)?db.favorites.filter(x=>x!==id):[...db.favorites,id];save();render()},preview:()=>{const q=db.current;modal(`<div class="tags"><span>主持人预览</span><span>${typeName(q.type)}</span></div><h2 style="line-height:1.9;margin-top:24px">${esc(q.text)}</h2><p class="fine">觉得适合今晚，就把这张纸条展示给大家。</p><div class="dialog-actions"><button class="secondary" data-action="preview-skip">换一张</button><button class="primary" data-action="reveal">展示给大家</button></div>`)},reveal:()=>{$('#dialog').close();revealed=true;render()},'preview-skip':()=>{$('#dialog').close();draw()},close:()=>$('#dialog').close(),'add-question':()=>questionForm(),'edit-question':questionForm,'delete-question':id=>confirmBox('删除这张纸条？','删除后可通过之前导出的备份找回。',()=>{db.questions=db.questions.filter(q=>q.id!==id);db.favorites=db.favorites.filter(x=>x!==id);if(db.current?.id===id)db.current=null;save();render()},'删除'),'add-player':()=>playerForm(),'edit-player':playerForm,'remove-player':id=>{db.players=db.players.filter(p=>p.id!==id);if(db.currentPlayer===id)db.currentPlayer='';if(db.partner===id)db.partner='';save();render()},filter:id=>{filterCat=id;render()},'add-category':()=>categoryForm(),'manage-category':categoryForm,'random-config':()=>{modal(`<form id="random-form"><h2>今晚的随机配方</h2><p class="fine">随机抽题时，包含哪些题库？</p><div class="checklist">${db.categories.map(c=>`<label><input type="checkbox" name="cat" value="${c.id}" ${db.randomCats.includes(c.id)?'checked':''}>${esc(c.symbol)} ${esc(c.name)}</label>`).join('')}</div><div class="dialog-actions"><button class="secondary" type="button" data-action="close">取消</button><button class="primary">保存配方</button></div></form>`);$('#random-form').onsubmit=e=>{e.preventDefault();let ids=new FormData(e.target).getAll('cat');if(!ids.length)return toast('至少选择一个题库');db.randomCats=ids;save();$('#dialog').close();render()}},export:()=>{const blob=new Blob([JSON.stringify({format:'heart-notes',version:1,exportedAt:new Date().toISOString(),data:db},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='心动纸条-备份-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出备份')},import:()=>$('#import-file').click()};
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b&&!b.disabled)actions[b.dataset.action]?.(b.dataset.id)});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.setting){db[t.dataset.setting]=t.checked;if(t.dataset.setting==='preview')revealed=!t.checked;save();render()}if(t.id==='current-player'){db.currentPlayer=t.value;if(db.partner===t.value)db.partner='';save();render()}if(t.id==='partner'){db.partner=t.value;save();render()}if(t.id==='filter-type'){filterType=t.value;render()}if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>5e6)throw Error();const data=JSON.parse(await t.files[0].text());if(!validBackup(data))throw Error();modal(`<h2>怎样导入这份备份？</h2><p class="fine">包含 ${data.data.questions.length} 张纸条、${data.data.players.length} 位玩家。</p><p class="fine">合并题库：加入题库和题目，保留当前玩家与进度。<br>完整恢复：用备份替换当前全部数据。</p><div class="dialog-actions"><button class="secondary" data-action="close">取消</button><button class="secondary" id="merge-backup">合并题库</button><button class="primary" id="restore-backup">完整恢复</button></div>`);$('#merge-backup').onclick=()=>{const cats=new Map();for(const c of data.data.categories){let existing=db.categories.find(x=>x.id===c.id||x.name===c.name);if(existing)cats.set(c.id,existing.id);else{let id=uid();db.categories.push({...c,id});db.randomCats.push(id);cats.set(c.id,id)}}let count=0;for(const q of data.data.questions){const category=cats.get(q.category);if(!db.questions.some(x=>x.text===q.text&&x.type===q.type&&x.category===category)){db.questions.push({...q,id:uid(),category});count++}}save();$('#dialog').close();render();toast('已合并 '+count+' 张新纸条')};$('#restore-backup').onclick=()=>confirmBox('替换当前全部数据？','当前题库、收藏、玩家与进度将被这份备份覆盖。',()=>{db={...defaults(),...data.data};revealed=!db.preview;save();render();toast('完整备份已恢复')},'恢复备份')}catch{toast('备份格式不正确，请选择心动纸条导出的 JSON 文件')}t.value=''}});
function validBackup(b){if(b?.format!=='heart-notes'||b.version!==1||!b.data)return false;const d=b.data,str=(x,n=1000)=>typeof x==='string'&&x.length>0&&x.length<=n,arr=(x)=>Array.isArray(x)&&x.length<=20000;if(!arr(d.categories)||!d.categories.length||!arr(d.questions)||!arr(d.players)||!arr(d.favorites)||!arr(d.seen))return false;if(!d.categories.every(c=>str(c.id,100)&&str(c.name,12)&&str(c.symbol,10))||new Set(d.categories.map(c=>c.id)).size!==d.categories.length)return false;const cats=new Set(d.categories.map(c=>c.id));if(!d.questions.every(q=>str(q.id,100)&&cats.has(q.category)&&['truth','dare'].includes(q.type)&&str(q.text)&&['轻松','微甜','走心','刺激'].includes(q.level)&&[1,2].includes(q.people))||new Set(d.questions.map(q=>q.id)).size!==d.questions.length)return false;const ids=new Set(d.questions.map(q=>q.id));return d.players.every(p=>str(p.id,100)&&str(p.name,12))&&new Set(d.players.map(p=>p.id)).size===d.players.length&&d.favorites.every(x=>ids.has(x))&&d.seen.every(x=>typeof x==='string')&&Array.isArray(d.randomCats)&&d.randomCats.every(x=>cats.has(x))&&['mix','truth','dare'].includes(d.type)&&['manual','random'].includes(d.playerMode)&&typeof d.preview==='boolean'&&typeof d.unique==='boolean'&&Number.isSafeInteger(d.round)&&d.round>=0&&(d.selected==='random'||d.selected==='favorites'||cats.has(d.selected))&&typeof d.currentPlayer==='string'&&typeof d.partner==='string'&&(d.current===null||d.questions.some(q=>JSON.stringify(q)===JSON.stringify(d.current)))}
render();
